/**
 * Phase115: Combine independent read-only Phase114 missing GTT restart
 * census with Phase104 full-page historical FO trade ID matching, and a
 * later fresh broker net. NO broker/local writes, no release or P&L.
 *
 * Upstox completed GTT parent is not retrievable and historical FO trades
 * do not reliably expose order_id or F&O instrument_token. Even a complete
 * trade_id/contract match is NOT independent proof that an orphan SELL was
 * generated by the GTT, or an independently signed venue settlement.
 */
import type {RestartGttReport} from './adaptiveNrmlMissingGttRestartQuarantine.js';
import type {HistoricalFoReport} from './adaptiveHistoricalFoTradeReview.js';
const uint=(x:unknown):x is number=>
  typeof x==='number'&&Number.isSafeInteger(x)&&x>=0;
const pos=(x:unknown):x is number=>uint(x)&&x>0;
const net=(x:unknown):number|null=>{
  if(uint(x))return x;
  if(typeof x==='string'&&/^(?:0|[1-9][0-9]*)$/.test(x)){
    const n=Number(x);return uint(n)?n:null;
  }
  return null;
};
export interface MissingGttHistoricalExitScope{
  originalLongQuantity:number;
  lotSize:number;
  immutableBuyTradeCount:number;
  immutableSellTradeCount:number;
  immutableSellFilledQuantity:number;
}
export interface MissingGttHistoricalExitSources{
  restart:RestartGttReport|null|undefined;
  history:HistoricalFoReport|null|undefined;
  freshBrokerNet:unknown;
}
export type MissingGttHistoricalExitState=
  'INVALID_SCOPE'|
  'RESTART_GTT_ACCOUNT_OR_NET_NOT_VERIFIED'|
  'TRIGGERED_GTT_CHILD_MUST_USE_SEPARATE_PHASE113_AUDIT'|
  'IMMUTABLE_SELL_EXECUTION_RECEIPTS_INCOMPLETE'|
  'HISTORICAL_FO_SOURCE_OR_ORIGINAL_TRADE_MATCH_INCOMPLETE'|
  'HISTORICAL_SELL_QUANTITY_OR_BROKER_NET_CONFLICT'|
  'BROKER_REPORTED_HISTORICAL_BUY_SELL_MATCH_NO_GTT_CLOSE_CERTIFICATE';
export interface MissingGttHistoricalExitReport{
  state:MissingGttHistoricalExitState;
  reasonCodes:readonly string[];
  brokerReportedCurrentNetQuantity:number|null;
  immutableSellFilledQuantity:number|null;
  brokerHistoricalMatchedBuyTradeCount:number;
  brokerHistoricalMatchedSellTradeCount:number;
  brokerHistoricalReadPageCount:number;
  gttParentMissingAcrossTwoReads:boolean;
  orphanGttSellChildSeenInCurrentDayBook:boolean;
  brokerReportedFlatPosition:boolean;
  historicalTradeIdsDescriptivelyMatched:boolean;
  trueGttParentCompletedOrCancelledIndependentlyVerified:false;
  historicalFoOrderIdAndInstrumentTokenLinkCertified:false;
  signedExchangeExecutionContractNotesVerified:false;
  completeBrokerAccountAcrossSessionsCertified:false;
  stopCloseOnlyAndNoShortCertified:false;
  stopChildVenueAckIndependentlyCertified:false;
  brokerSnapshotsAtomic:false;
  brokerGttSellGapFillGuaranteed:false;
  capitalMarginChargesAndTaxesReconciled:false;
  automaticPositionClosureAuthorized:false;
  realisedPnlWriteAuthorized:false;
  duplicateSellRetryAuthorized:false;
  gttCancelOrReplaceAuthorized:false;
  liveNrmlBuyAuthorized:false;
  brokerWrites:0;
  localWrites:0;
}
type Summary=Partial<Pick<MissingGttHistoricalExitReport,
  'brokerReportedCurrentNetQuantity'|'immutableSellFilledQuantity'|
  'brokerHistoricalMatchedBuyTradeCount'|
  'brokerHistoricalMatchedSellTradeCount'|
  'brokerHistoricalReadPageCount'|'gttParentMissingAcrossTwoReads'|
  'orphanGttSellChildSeenInCurrentDayBook'|
  'brokerReportedFlatPosition'|'historicalTradeIdsDescriptivelyMatched'>>;
const report=(state:MissingGttHistoricalExitState,reasons:string[],
  d:Summary={}):MissingGttHistoricalExitReport=>({
  state,reasonCodes:[...new Set(reasons)].sort(),
  brokerReportedCurrentNetQuantity:
    d.brokerReportedCurrentNetQuantity??null,
  immutableSellFilledQuantity:d.immutableSellFilledQuantity??null,
  brokerHistoricalMatchedBuyTradeCount:
    d.brokerHistoricalMatchedBuyTradeCount??0,
  brokerHistoricalMatchedSellTradeCount:
    d.brokerHistoricalMatchedSellTradeCount??0,
  brokerHistoricalReadPageCount:d.brokerHistoricalReadPageCount??0,
  gttParentMissingAcrossTwoReads:d.gttParentMissingAcrossTwoReads===true,
  orphanGttSellChildSeenInCurrentDayBook:
    d.orphanGttSellChildSeenInCurrentDayBook===true,
  brokerReportedFlatPosition:d.brokerReportedFlatPosition===true,
  historicalTradeIdsDescriptivelyMatched:
    d.historicalTradeIdsDescriptivelyMatched===true,
  trueGttParentCompletedOrCancelledIndependentlyVerified:false,
  historicalFoOrderIdAndInstrumentTokenLinkCertified:false,
  signedExchangeExecutionContractNotesVerified:false,
  completeBrokerAccountAcrossSessionsCertified:false,
  stopCloseOnlyAndNoShortCertified:false,
  stopChildVenueAckIndependentlyCertified:false,
  brokerSnapshotsAtomic:false,brokerGttSellGapFillGuaranteed:false,
  capitalMarginChargesAndTaxesReconciled:false,
  automaticPositionClosureAuthorized:false,
  realisedPnlWriteAuthorized:false,duplicateSellRetryAuthorized:false,
  gttCancelOrReplaceAuthorized:false,liveNrmlBuyAuthorized:false,
  brokerWrites:0,localWrites:0
});
const valid=(s:MissingGttHistoricalExitScope):boolean=>!!s&&
  pos(s.originalLongQuantity)&&pos(s.lotSize)&&
  s.originalLongQuantity%s.lotSize===0&&
  pos(s.immutableBuyTradeCount)&&s.immutableBuyTradeCount<=5000&&
  pos(s.immutableSellTradeCount)&&s.immutableSellTradeCount<=5000&&
  pos(s.immutableSellFilledQuantity)&&
  s.immutableSellFilledQuantity<=s.originalLongQuantity;
const missing=new Set([
  'MISSING_GTT_PARENT_REQUIRES_BROKER_HISTORY_MANUAL_REVIEW',
  'MISSING_GTT_ORPHAN_SELL_CHILD_MANUAL_REVIEW'
]);
/**
 * Execute only on trusted internally constructed Phase104/Phase114
 * reports from the SAME pinned broker account/credential generation.
 * No response should be fed into any live-order/risk-release gate.
 */
export function auditMissingGttHistoricalExitJoin(
  scope:MissingGttHistoricalExitScope,
  source:MissingGttHistoricalExitSources
):MissingGttHistoricalExitReport{
  if(!valid(scope))return report('INVALID_SCOPE',
    ['ORIGINAL_BUY_SELL_TRADE_RECEIPT_QUANTITY_OR_LOT_INVALID']);
  if(!source||!source.restart||source.restart.brokerReadPasses!==2||
     source.restart.brokerWrites!==0||source.restart.localWrites!==0||
     source.restart.duplicateSellRetryAuthorized!==false||
     source.restart.closedPositionWriteAuthorized!==false||
     source.restart.originalLongQuantity!==scope.originalLongQuantity)
    return report('RESTART_GTT_ACCOUNT_OR_NET_NOT_VERIFIED',
      ['SAME_ACCOUNT_TWO_PASS_RESTART_RECEIPT_OR_GTT_HISTORY_UNAVAILABLE']);
  const r=source.restart;
  if(r.state==='GENERATED_SELL_CHILD_REQUIRES_TRADE_NET_AUDIT')
    return report('TRIGGERED_GTT_CHILD_MUST_USE_SEPARATE_PHASE113_AUDIT',
      ['GTT_RETRIEVABLE_CHILD_ORDER_TRADES_NET_MUST_BE_RECONCILED_FIRST']);
  if(!missing.has(r.state)||r.brokerReportedGttPresent)
    return report('RESTART_GTT_ACCOUNT_OR_NET_NOT_VERIFIED',
      ['GTT_NOT_IN_MISSING_PARENT_RESTART_QUARANTINE_STATE']);
  const current=net(r.brokerReportedCurrentNrmlNet);
  const fresh=net(source.freshBrokerNet);
  const base:Summary={
    immutableSellFilledQuantity:scope.immutableSellFilledQuantity,
    gttParentMissingAcrossTwoReads:true,
    orphanGttSellChildSeenInCurrentDayBook:
      r.state==='MISSING_GTT_ORPHAN_SELL_CHILD_MANUAL_REVIEW'
  };
  if(current===null||fresh===null||fresh!==current||
     current>scope.originalLongQuantity||current%scope.lotSize!==0&&
       current!==0)
    return report('RESTART_GTT_ACCOUNT_OR_NET_NOT_VERIFIED',
      ['BROKER_NET_CHANGED_OR_NONWHOLE_LOT_AFTER_HISTORICAL_GET'],base);
  base.brokerReportedCurrentNetQuantity=current;
  base.brokerReportedFlatPosition=current===0;
  // Strictly require already durable original BUY and exit SELL trade IDs.
  // Do not infer an exit from current net alone, or supply synthetic trade ID.
  if(!source.history||!uint(source.history.matchedOriginalBuyTrades)||
     !uint(source.history.matchedExitSellTrades)||
     source.history.requestedPageCount<1)
    return report('HISTORICAL_FO_SOURCE_OR_ORIGINAL_TRADE_MATCH_INCOMPLETE',
      ['BROKER_HISTORICAL_TRADE_PAGES_OR_DURABLE_RECEIPTS_UNAVAILABLE'],base);
  const h=source.history;
  base.brokerHistoricalMatchedBuyTradeCount=h.matchedOriginalBuyTrades;
  base.brokerHistoricalMatchedSellTradeCount=h.matchedExitSellTrades;
  base.brokerHistoricalReadPageCount=h.requestedPageCount;
  if(h.state!=='BROKER_REPORTED_MULTIDAY_TRADES_MATCH_NOT_CERTIFIED'||
     h.matchedOriginalBuyTrades!==scope.immutableBuyTradeCount||
     h.matchedExitSellTrades!==scope.immutableSellTradeCount||
     h.otherSameContractTrades!==0||
     h.brokerWrites!==0||h.localWrites!==0||
     h.automaticClosureAuthorized!==false||
     h.historicalTradesIndependentlyCertified!==false||
     h.brokerHistoricalOrderIdPresent!==false||
     h.brokerHistoricalInstrumentTokenPresent!==false)
    return report('HISTORICAL_FO_SOURCE_OR_ORIGINAL_TRADE_MATCH_INCOMPLETE',
      ['ORIGINAL_BUY_SELL_TRADE_IDS_OR_FO_PAGINATION_NOT_ALL_MATCHED'],base);
  const expected=scope.originalLongQuantity-scope.immutableSellFilledQuantity;
  if(current!==expected)
    return report('HISTORICAL_SELL_QUANTITY_OR_BROKER_NET_CONFLICT',
      ['IMMUTABLE_EXIT_EXECUTIONS_DISAGREE_WITH_BROKER_REMAINING_LONG'],base);
  return report('BROKER_REPORTED_HISTORICAL_BUY_SELL_MATCH_NO_GTT_CLOSE_CERTIFICATE',[
    'BROKER_FO_TRADE_ID_MATCH_DOES_NOT_IDENTIFY_MISSING_GTT_CHILD_ORDER',
    'BROKER_FO_HISTORY_LACKS_ORDER_ID_AND_FO_INSTRUMENT_TOKEN',
    'SIGNED_EXCHANGE_CONTRACT_NOTES_AND_NATIVE_STOP_COVERAGE_MISSING',
    'CURRENT_NET_AND_HISTORICAL_PAGES_NOT_TRANSACTION_ATOMIC'
  ],{...base,historicalTradeIdsDescriptivelyMatched:true});
}
